function bindPost(post){const like=post.querySelector('.like');if(like)like.onclick=()=>{like.classList.toggle('liked');const count=like.querySelector('.count');count.textContent=+count.textContent+(like.classList.contains('liked')?1:-1)};const toggle=post.querySelector('.comment-toggle');if(toggle)toggle.onclick=()=>post.querySelector('.comments').classList.toggle('open');post.querySelectorAll('.share').forEach(x=>x.onclick=()=>{navigator.clipboard?.writeText(location.href);toast('Ссылка скопирована')});const form=post.querySelector('.comment-form');if(form)form.onsubmit=e=>{e.preventDefault();const input=form.querySelector('input');if(input.value.trim()){const c=document.createElement('div');c.className='comment';c.innerHTML='<div class="avatar sm">AK</div><p><b>Вы</b> '+input.value.replace(/[<>]/g,'')+'</p>';form.before(c);input.value='';toast('Комментарий добавлен')}}}
