const date=t=>new Date(t).toLocaleDateString('ru',{day:'numeric',month:'short'});
let db,S,ready=false,view='messages',filter='all',activeChat=null,activeCommunity=null,activeChannel='general',draftFile=null,focusBefore=null,objectURLs=[];
const attachmentURLs=new Map();
function fileURL(file){if(!file)return '';if(!attachmentURLs.has(file))attachmentURLs.set(file,URL.createObjectURL(file));return attachmentURLs.get(file)}
const me=()=>S.accounts.find(a=>a.id===S.session)||S.accounts[0];
const seed=()=>({version:3,session:'local',accounts:[{id:'local',name:'Новый пользователь',handle:'username',bio:'',email:'',avatar:null}],settings:{light:false,push:true,autoplay:false,private:true},posts:[],communities:[],chats:[],videos:[],notices:[]});
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('messenger-clean-start-v3',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Хранилище занято другой вкладкой'))});S=await new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(!S)S=seed();else if(S.version<3){S=seed()}}catch(e){S=seed();toast('Хранилище недоступно: изменения останутся до закрытия страницы')}
async function save(){if(!db){toast('Режим памяти: данные не сохраняются после закрытия');return false}try{await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(S,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});$('#storageStatus').textContent='Сохранено на устройстве';return true}catch(e){$('#storageStatus').textContent='Не удалось сохранить';toast('Не удалось сохранить: проверьте свободное место и доступ к хранилищу');return false}}
function notify(text,target='home',ref=''){if(S.settings.push)S.notices.unshift({id:uid(),text,target,ref,time:Date.now(),read:false});renderNotices()}
function go(id){view=id;document.querySelector('[data-view="'+id+'"]').click();$('#searchResults').classList.remove('open');if(id==='profile')renderProfile();if(id==='messages')renderChats();if(id==='communities')renderCommunities();if(id==='videos')renderVideos();if(id==='notifications')renderNotices()}
function work(title,html){focusBefore=document.activeElement;$('#workTitle').textContent=title;$('#workBody').innerHTML=html;openModal('workModal');setTimeout(()=>$('#workBody input, #workBody textarea, #workBody button')?.focus(),40)}
function empty(title,desc){return '<div class="empty"><strong>'+esc(title)+'</strong>'+esc(desc)+'</div>'}
function avatar(account,cls=''){return account.avatar?'<img class="avatar '+cls+'" alt="" src="'+fileURL(account.avatar)+'" style="object-fit:cover">':'<div class="avatar '+cls+'">'+esc(initials(account.name))+'</div>'}
function applyIdentity(){const a=me();$('.mini-profile .who strong').textContent=a.name;$('.mini-profile .who span').textContent='@'+a.handle;$('.mini-profile .avatar').outerHTML=avatar(a);$('.top-actions>.avatar').outerHTML=avatar(a,'sm');$('.composer-head .avatar').outerHTML=avatar(a);$('#fakeInput').textContent='Чем поделитесь, '+a.name.split(' ')[0]+'?';$('#loginBtn').textContent=a.id==='local'?'Войти':'Аккаунт';renderProfile();$('.side-stack .profile-card').innerHTML=profileHTML(a);}
function profileHTML(a){return '<div class="cover"></div>'+avatar(a,'lg')+'<h3>'+esc(a.name)+'</h3><span class="handle">@'+esc(a.handle)+'</span><p>'+esc(a.bio||'Добавьте пару слов о себе')+'</p><div class="stats"><div><b>'+S.posts.filter(p=>p.owner===a.id).length+'</b><span>Публикации</span></div><div><b>'+S.communities.filter(c=>c.members.includes(a.id)).length+'</b><span>Сообщества</span></div><div><b>'+S.posts.filter(p=>p.savedBy.includes(a.id)).length+'</b><span>Сохранено</span></div></div>'}
function renderProfile(){$('#profile .profile-card').innerHTML=profileHTML(me());$('#profilePosts').innerHTML=S.posts.filter(p=>p.owner===me().id).map(postHTML).join('')||empty('Ваша история начинается здесь','Создайте первую публикацию в ленте.');bindPosts($('#profilePosts'))}
function mediaHTML(file){if(!file)return '';const u=fileURL(file);if(file.type.startsWith('image/'))return '<img class="post-photo" loading="lazy" alt="Вложение к публикации" src="'+u+'">';if(file.type.startsWith('video/'))return '<video class="post-video" controls preload="metadata" src="'+u+'"></video>';return '<div class="attachment">'+icons.file+'<a download="'+esc(file.name||'attachment')+'" href="'+u+'">'+esc(file.name||'Вложение')+' · '+(file.size/1048576).toFixed(1)+' МБ ↓</a></div>'}
function postHTML(p){const a=S.accounts.find(a=>a.id===p.owner);const own=p.owner===me().id;const liked=p.likedBy.includes(me().id),saved=p.savedBy.includes(me().id);return '<article class="card post" data-id="'+p.id+'"><div class="post-head">'+(a?avatar(a):p.initials?'<div class="avatar">'+esc(p.initials)+'</div>':'<div class="pulse-mark">'+mark+'</div>')+'<div class="post-meta"><strong>'+esc(a?.name||p.author)+'</strong><span>@'+esc(a?.handle||p.handle)+' · '+date(p.time)+(p.sample?' · пример':' · '+(p.visibility==='private'?'Только я':'Локально'))+'</span></div><button class="more" data-action="'+(own?'delete':'save')+'" title="'+(own?'Удалить публикацию':'Сохранить')+'">'+(own?'Удалить':'•••')+'</button></div><div class="post-body">'+esc(p.text)+'</div>'+mediaHTML(p.file)+'<div class="post-actions"><button class="like '+(liked?'liked':'')+'" data-action="like" aria-pressed="'+liked+'">'+icons.heart+' '+(p.likes+p.likedBy.length)+'</button><button data-action="comment">'+icons.message+' '+p.comments.length+'</button><button data-action="share">'+icons.share+' Поделиться</button><button data-action="save" class="'+(saved?'saved':'')+'" style="margin-left:auto" aria-label="Сохранить" aria-pressed="'+saved+'">'+icons.bookmark+'</button></div><div class="comments"><div class="comment-list">'+p.comments.map(c=>'<div class="comment"><div class="avatar sm">'+esc(initials(c.author))+'</div><p><b>'+esc(c.author)+'</b><br>'+esc(c.text)+'</p></div>').join('')+'</div><form class="comment-form"><input aria-label="Комментарий" placeholder="Добавить комментарий…" maxlength="2000" required><button>Отправить</button></form></div></article>'}
function renderFeed(){const ps=S.posts.filter(p=>filter==='all'||(filter==='mine'?p.owner===me().id:p.savedBy.includes(me().id)));$('#postList').innerHTML=ps.map(postHTML).join('')||empty(filter==='saved'?'Пока ничего не сохранено':'Здесь появятся публикации','Поделитесь мыслью или сохраните понравившуюся запись.');bindPosts($('#postList'));$$('#feedTabs button').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));renderProfile()}
function bindPosts(root){root.querySelectorAll('article').forEach(el=>{const p=S.posts.find(p=>p.id===el.dataset.id);el.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.action;if(action==='comment'){el.querySelector('.comments').classList.toggle('open');el.querySelector('input').focus();return}if(action==='delete'){work('Удалить публикацию?','<p class="hint">Публикация и комментарии будут удалены с этого устройства.</p><div class="modal-foot"><button class="ghost" id="cancelDelete">Отмена</button><button class="primary" id="confirmDelete">Удалить</button></div>');$('#cancelDelete').onclick=()=>closeModal('workModal');$('#confirmDelete').onclick=async()=>{S.posts=S.posts.filter(x=>x.id!==p.id);const ok=await save();closeModal('workModal');renderFeed();if(ok)toast('Публикация удалена')};return}if(action==='share'){const text=(S.accounts.find(a=>a.id===p.owner)?.name||p.author)+' в PULSE\n\n'+p.text;try{await navigator.clipboard.writeText(text);toast('Текст публикации скопирован')}catch(e){work('Поделиться публикацией','<p class="hint">Локальная публикация не имеет публичной ссылки. Скопируйте текст:</p><textarea style="width:100%;min-height:160px" readonly>'+esc(text)+'</textarea>');$('#workBody textarea').select()}return}const arr=action==='like'?p.likedBy:p.savedBy;const i=arr.indexOf(me().id);if(i<0)arr.push(me().id);else arr.splice(i,1);await save();renderFeed()});el.querySelector('form').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input'),text=input.value.trim();if(!text)return;p.comments.push({id:uid(),owner:me().id,author:me().name,text,time:Date.now()});notify('Добавлен комментарий к публикации','home',p.id);await save();renderFeed();const current=document.querySelector('[data-id="'+p.id+'"] .comments');current?.classList.add('open')}})}
function compose(attach=false){draftFile=null;$('#postText').value='';$('#draftName').textContent='';$('#postFile').value='';openModal('postModal');$('#postText').focus();if(attach)$('#postFile').click()}
$('#composeBtn').onclick=()=>compose();$('#fakeInput').onclick=()=>compose();$('#photoTool').onclick=()=>compose(true);$('.composer-tools .tool:nth-child(2)').onclick=()=>compose(true);$('.composer-tools .tool:nth-child(3)').onclick=()=>{compose();$('#postText').value='✨ Сегодня я '};$('#visibilityTool').onclick=()=>{compose();$('#postVisibility').focus()};
