$('#publishBtn').onclick=async()=>{const text=$('#postText').value.trim();if(!text&&!draftFile){toast('Напишите текст или добавьте файл');return}const a=me();S.posts.unshift({id:uid(),owner:a.id,text,time:Date.now(),visibility:$('#postVisibility').value,file:draftFile,likes:0,likedBy:[],savedBy:[],comments:[]});notify('Ваша публикация добавлена в ленту');$('#publishBtn').disabled=true;const ok=await save();$('#publishBtn').disabled=false;closeModal('postModal');filter='all';renderFeed();if(ok)toast('Публикация сохранена на устройстве')};
function renderCommunities(){$('#communityGrid').innerHTML=S.communities.map((c,i)=>'<div class="card community"><div class="cover" style="background:radial-gradient(circle at 75% 20%,#4edcff50,transparent 25%),linear-gradient(125deg,'+['#12316d','#361e5e','#123e4b'][i%3]+',#0a1223)"></div><div class="community-body"><span class="pill">'+(c.sample?'Пример сообщества':'Ваше сообщество')+'</span><h3 style="margin-top:14px"><button data-open="'+c.id+'">'+esc(c.name)+'</button></h3><p style="min-height:35px;line-height:1.7">'+esc(c.description)+'</p><div class="community-footer"><span class="hint">'+c.channels.length+' канала · '+c.members.length+' лок. участн.</span><button data-join="'+c.id+'">'+(c.members.includes(me().id)?'Вы участник ✓':'Вступить')+'</button><button data-open="'+c.id+'">Открыть →</button></div></div></div>').join('');$$('[data-join]').forEach(b=>b.onclick=async()=>{const c=S.communities.find(c=>c.id===b.dataset.join),i=c.members.indexOf(me().id);if(i<0)c.members.push(me().id);else c.members.splice(i,1);await save();renderCommunities();applyIdentity()});$$('[data-open]').forEach(b=>b.onclick=()=>openCommunity(b.dataset.open))}
$('#createCommunity').onclick=()=>{work('Новое сообщество','<form id="communityForm" class="form-stack"><label class="field">Название<input id="communityName" maxlength="60" required placeholder="Например, Digital Garden"></label><label class="field">О чём сообщество<textarea id="communityDescription" maxlength="500" required placeholder="Кому здесь будет интересно?"></textarea></label><p class="hint">Сообщество и его каналы доступны только на этом устройстве. Приглашения другим людям требуют сервера.</p><button class="primary">Создать сообщество</button></form>');$('#communityForm').onsubmit=async e=>{e.preventDefault();const name=$('#communityName').value.trim(),description=$('#communityDescription').value.trim();if(!name||!description)return;const c={id:uid(),name,description,owner:me().id,members:[me().id],channels:['general','ideas'],messages:{}};S.communities.unshift(c);notify('Создано сообщество «'+name+'»','communities',c.id);const ok=await save();closeModal('workModal');renderCommunities();if(ok)toast('Сообщество создано');openCommunity(c.id)}};
function openCommunity(id,channel='general'){activeCommunity=id;activeChannel=channel;const c=S.communities.find(c=>c.id===id);if(!c)return;work(c.name,'<p class="hint">'+esc(c.description)+' · Локальное пространство</p><div class="channels"><div class="channel-list">'+c.channels.map(ch=>'<button data-channel="'+esc(ch)+'" class="'+(ch===channel?'active':'')+'"># '+esc(ch)+'</button>').join('')+'<button id="addChannel">+ Канал</button></div><div class="channel-chat"><div class="chat-body" id="channelBody">'+(c.messages[channel]||[]).map(m=>'<div class="bubble me"><b>'+esc(m.author)+'</b><br>'+esc(m.text)+'<time>'+clock(m.time)+'</time></div>').join('')+'</div><form class="chat-send" id="channelForm"><input required maxlength="3000" placeholder="Сообщение в #'+esc(channel)+'" aria-label="Сообщение в канал"><button class="primary">↑</button></form></div></div>');if(!(c.messages[channel]||[]).length)$('#channelBody').innerHTML=empty('# '+channel,'Начните обсуждение. Сообщения хранятся на этом устройстве.');$$('[data-channel]').forEach(b=>b.onclick=()=>openCommunity(id,b.dataset.channel));$('#addChannel').onclick=()=>{work('Добавить канал','<form class="form-stack" id="channelCreate"><label class="field">Название канала<input id="newChannelName" required pattern="[a-z0-9_-]{1,30}" placeholder="design-notes" maxlength="30"></label><p class="hint">Латинские буквы, цифры, дефис или подчёркивание.</p><button class="primary">Добавить</button></form>');$('#channelCreate').onsubmit=async e=>{e.preventDefault();const name=$('#newChannelName').value.toLowerCase();if(c.channels.includes(name)){toast('Канал уже существует');return}c.channels.push(name);await save();openCommunity(id,name)}};$('#channelForm').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('input'),text=input.value.trim();if(!text)return;if(!c.members.includes(me().id)){toast('Сначала вступите в сообщество');return}(c.messages[channel]??=[]).push({id:uid(),owner:me().id,text,author:me().name,time:Date.now()});await save();openCommunity(id,channel);$('#channelBody').scrollTop=999999};$('#channelBody').scrollTop=999999}
function renderChats(){
  $('.conversation-list').innerHTML='<h3>Чаты</h3>'+S.chats.map(c=>'<div class="conversation '+(activeChat===c.id?'selected':'')+'" role="button" tabindex="0" data-room="'+c.id+'"><div class="avatar sm">'+esc(initials(c.name))+'</div><div class="who"><strong>'+esc(c.name)+'</strong><p>'+esc(c.messages.at(-1)?.text||'Новый диалог')+'</p></div></div>').join('')||empty('Пока нет чатов','Начните переписку — нажмите «Новый чат».');
  $$('[data-room]').forEach(el=>{el.onclick=()=>{activeChat=el.dataset.room;renderChats()};el.onkeydown=e=>{if(e.key==='Enter')el.click()}});
  const c=S.chats.find(c=>c.id===activeChat)||S.chats[0];
  if(!c){activeChat=null;$('#chatName').textContent='Ваши сообщения';$('.chat-top .avatar').textContent='…';$('.chat-top span').textContent='Личные и групповые чаты';$('#chatBody').innerHTML=empty('Выберите чат','Когда вы начнёте переписку, сообщения появятся здесь.');$('#chatInput').disabled=true;$('#chatForm button').disabled=true;return}
  activeChat=c.id;$('#chatInput').disabled=false;$('#chatForm button').disabled=false;$('#chatName').textContent=c.name;$('.chat-top .avatar').textContent=initials(c.name);$('.chat-top span').textContent='Локальный диалог · без сервера';$('#chatBody').innerHTML=c.messages.map(m=>'<div class="bubble '+(m.mine?'me':'')+'">'+esc(m.text)+'<time>'+clock(m.time)+'</time></div>').join('')||empty('Начните разговор','Сообщения сохраняются локально; доставка другому человеку не подключена.');$('#chatBody').scrollTop=999999
}
$('#chatForm').onsubmit=async e=>{e.preventDefault();const input=$('#chatInput'),text=input.value.trim();if(!text||!activeChat)return;S.chats.find(c=>c.id===activeChat).messages.push({id:uid(),text,mine:true,owner:me().id,time:Date.now()});input.value='';await save();renderChats()};$('#chatInput').maxLength=5000;
$('#newChat').onclick=()=>{work('Новый локальный чат','<form id="newChatForm" class="form-stack"><label class="field">Имя или название<input id="newChatName" required maxlength="60" placeholder="Например, Команда проекта"></label><p class="hint">Это локальный блокнот диалога. Реальная отправка, онлайн-статус и групповые звонки требуют сервера и здесь не имитируются.</p><button class="primary">Создать чат</button></form>');$('#newChatForm').onsubmit=async e=>{e.preventDefault();const name=$('#newChatName').value.trim();if(!name)return;const c={id:uid(),name,owner:me().id,messages:[]};S.chats.unshift(c);activeChat=c.id;await save();closeModal('workModal');go('messages')}};
function renderVideos(){$('#videoGrid').innerHTML='<div class="card video-card"><div class="thumb" style="background:linear-gradient(125deg,#103d78,#0a1222)"><button class="play" id="sampleVideo" aria-label="Создать пример ролика">'+icons.plus+'</button><strong>СОЗДАЙТЕ ПЕРВЫЙ СИГНАЛ</strong></div><div class="video-body"><h3>Ваша личная видеотека</h3><p style="line-height:1.7">Загрузите MP4 / WebM с устройства или создайте короткий пример прямо здесь.</p><span class="pill">Без внешних ресурсов</span></div></div>'+S.videos.map(v=>'<div class="card video-card"><div class="thumb" data-video="'+v.id+'" role="button" tabindex="0"><button class="play" aria-label="Смотреть '+esc(v.title)+'">'+icons.play+'</button><strong>'+date(v.time)+' · '+(v.file.size/1048576).toFixed(1)+' МБ</strong></div><div class="video-body"><h3>'+esc(v.title)+'</h3><p>'+esc(v.description||'Локальный ролик')+'</p><div class="button-row"><span class="pill">'+v.views+' лок. запусков</span><button class="tool" data-remove-video="'+v.id+'">Удалить</button></div></div></div>').join('');$('#sampleVideo').onclick=generateSample;$$('[data-video]').forEach(el=>{el.onclick=()=>playVideo(el.dataset.video);el.onkeydown=e=>{if(e.key==='Enter')el.click()}});$$('[data-remove-video]').forEach(b=>b.onclick=()=>{const id=b.dataset.removeVideo;work('Удалить ролик?','<p class="hint">Ролик будет удалён из локальной видеотеки.</p><button class="primary" id="confirmVideoDelete">Удалить</button>');$('#confirmVideoDelete').onclick=async()=>{S.videos=S.videos.filter(v=>v.id!==id);await save();closeModal('workModal');renderVideos()}})}
function playVideo(id){const v=S.videos.find(v=>v.id===id);if(!v)return;v.views++;save();work(v.title,'<video class="player" controls playsinline preload="metadata" src="'+fileURL(v.file)+'"></video><p class="hint">'+esc(v.description||'Ваш локальный ролик')+'</p><p class="hint">'+(v.file.size/1048576).toFixed(1)+' МБ · Хранится на этом устройстве</p>');const video=$('#workBody video');video.onerror=()=>toast('Формат ролика не поддерживается этим браузером');video.play().catch(()=>{});renderVideos()}
$('#uploadBtn').onclick=()=>{work('Загрузить видео','<form id="videoUploadForm" class="form-stack"><label class="field">Название<input id="videoTitle" required maxlength="100" placeholder="У каждой идеи есть своя история"></label><label class="field">Описание<textarea id="videoDescription" maxlength="2000" placeholder="О чём этот ролик?"></textarea></label><label class="field">Видеофайл<input id="videoFile" type="file" accept="video/*" required></label><p class="hint">До 60 МБ. Рекомендуем MP4 или WebM. Файл сохраняется в IndexedDB, а не отправляется в интернет.</p><p class="error" id="videoError"></p><button class="primary">Сохранить в видеотеку</button></form>');$('#videoUploadForm').onsubmit=async e=>{e.preventDefault();const f=$('#videoFile').files[0],title=$('#videoTitle').value.trim();if(!f||!title)return;if(!f.type.startsWith('video/')||f.size>60*1048576){$('#videoError').textContent='Выберите видео размером до 60 МБ.';return}S.videos.unshift({id:uid(),title,description:$('#videoDescription').value.trim(),file:f,time:Date.now(),views:0,owner:me().id});notify('Добавлен ролик «'+title+'»','videos');const ok=await save();closeModal('workModal');renderVideos();if(ok)toast('Видео сохранено')}};
async function generateSample(){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast('Генерация не поддерживается браузером. Загрузите свой ролик.');return}const btn=$('#sampleVideo');btn.disabled=true;toast('Генерируем 4-секундный ролик на устройстве…');try{const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;const ctx=canvas.getContext('2d'),stream=canvas.captureStream(30),chunks=[];const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/mp4','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};let frame=0,start=performance.now();function draw(now){const t=(now-start)/1000;ctx.fillStyle='#060d1c';ctx.fillRect(0,0,960,540);const glow=ctx.createRadialGradient(480+Math.sin(t)*140,270,0,480,270,500);glow.addColorStop(0,'#123f70');glow.addColorStop(1,'#060d1c');ctx.fillStyle=glow;ctx.fillRect(0,0,960,540);ctx.strokeStyle='#42d6ff';ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowBlur=25;ctx.shadowColor='#268eff';ctx.beginPath();const x=200+Math.sin(t*2)*16;[[x,235],[x+80,235],[x+116,166],[x+168,310],[x+210,205],[x+240,235],[x+300,235]].forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#effaff';ctx.font='bold 85px system-ui';ctx.fillText('ULSE',x+320,267);ctx.fillStyle='#7ea6cc';ctx.font='18px system-ui';ctx.fillText('ONE PLATFORM. EVERYTHING CONNECTED.',240,375);frame=requestAnimationFrame(draw)}draw(start);const stopped=new Promise(resolve=>recorder.onstop=resolve);recorder.start();await new Promise(r=>setTimeout(r,4000));recorder.stop();await stopped;cancelAnimationFrame(frame);stream.getTracks().forEach(t=>t.stop());const file=new File(chunks,['pulse-signal.',recorder.mimeType.includes('mp4')?'mp4':'webm'].join(''),{type:recorder.mimeType});S.videos.unshift({id:uid(),title:'Первый сигнал — PULSE',description:'Сгенерировано в браузере · 4 секунды · без звука',file,time:Date.now(),views:0,owner:me().id});const ok=await save();renderVideos();if(ok)toast('Ролик готов — нажмите, чтобы посмотреть')}catch(e){toast('Не удалось создать пример. Загрузите видео с устройства.');if(btn)btn.disabled=false}}
function renderNotices(){const n=S.notices.filter(n=>!n.read).length;$('#noticeList').innerHTML='<div class="side-head"><h3>События на этом устройстве</h3><span class="pill">'+n+' новых</span></div>'+(S.notices.map(x=>'<button class="notice-row '+(!x.read?'unread':'')+'" data-notice="'+x.id+'"><div class="pulse-mark">'+mark+'</div><div class="who"><strong>'+esc(x.text)+'</strong><span>'+date(x.time)+' · '+clock(x.time)+'</span></div></button>').join('')||empty('Вы ничего не пропустили','Здесь появятся события о ваших публикациях, видео и сообществах.'));$$('[data-notice]').forEach(b=>b.onclick=async()=>{const x=S.notices.find(n=>n.id===b.dataset.notice);x.read=true;await save();go(x.target);if(x.target==='communities'&&x.ref)openCommunity(x.ref);renderNotices()});const badge=$('#mainNav [data-view="notifications"] .badge');badge.textContent=n;badge.style.display=n?'grid':'none';$('#notifBtn .dot').style.display=n?'block':'none';const msg=$('#mainNav [data-view="messages"] .badge');msg.style.display='none'}
$('#markRead').onclick=async()=>{S.notices.forEach(n=>n.read=true);await save();renderNotices()};$('#notifBtn').onclick=()=>go('notifications');
$('#editProfile').onclick=()=>{const a=me();work('Редактировать профиль','<form id="profileForm" class="form-stack"><label class="field">Имя<input id="profileName" required maxlength="60" value="'+esc(a.name)+'"></label><label class="field">Имя пользователя<input id="profileHandle" required pattern="[a-zA-Z0-9_]{3,30}" maxlength="30" value="'+esc(a.handle)+'"></label><label class="field">О себе<textarea id="profileBio" maxlength="300">'+esc(a.bio)+'</textarea></label><label class="field">Аватар<input type="file" id="profileAvatar" accept="image/*"></label><p class="hint">Аватар до 4 МБ. Изменения сохраняются только на устройстве.</p><p class="error" id="profileError"></p><button class="primary">Сохранить</button></form>');$('#profileForm').onsubmit=async e=>{e.preventDefault();const name=$('#profileName').value.trim(),handle=$('#profileHandle').value.toLowerCase(),f=$('#profileAvatar').files[0];if(!name)return;if(S.accounts.some(x=>x.id!==a.id&&x.handle===handle)){$('#profileError').textContent='Это имя пользователя уже занято локальным профилем';return}if(f&&(!f.type.startsWith('image/')||f.size>4*1048576)){$('#profileError').textContent='Выберите изображение до 4 МБ';return}a.name=name;a.handle=handle;a.bio=$('#profileBio').value.trim();if(f)a.avatar=f;const ok=await save();applyIdentity();renderFeed();closeModal('workModal');if(ok)toast('Профиль обновлён')}};
async function digest(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function accountModal(register=false){if(me().id!=='local'&&!register){work('Локальный аккаунт',avatar(me(),'lg')+'<h3>'+esc(me().name)+'</h3><p class="hint">'+esc(me().email)+'</p><p class="hint">Этот аккаунт существует только в данном браузере. Локальный пароль не обеспечивает защиту данных от владельца устройства и не является серверной авторизацией.</p><button class="primary" id="logout">Выйти в гостевой профиль</button>');$('#logout').onclick=async()=>{S.session='local';await save();closeModal('workModal');applyIdentity();renderFeed()};return}work(register?'Создать локальный аккаунт':'Войти в локальный аккаунт','<div style="margin-bottom:15px">'+brand+'</div><form id="localAuthForm" class="form-stack">'+(register?'<label class="field">Имя<input id="authName" required maxlength="60" autocomplete="name"></label>':'')+'<label class="field">Email<input id="authEmail" type="email" required autocomplete="email" maxlength="120"></label><label class="field">Пароль<input id="authPassword" type="password" minlength="8" maxlength="128" required autocomplete="'+(register?'new-password':'current-password')+'"></label><p class="error" id="authError"></p><button class="primary" id="authSubmit">'+(register?'Создать аккаунт':'Войти')+'</button><button type="button" class="ghost" id="authSwitch">'+(register?'Уже есть локальный аккаунт':'Создать аккаунт')+'</button><p class="hint">Только на этом устройстве. Пароль сохраняется как PBKDF2-хеш с солью. Нет серверной авторизации, подтверждения email и восстановления пароля. Не используйте пароль от других сервисов.</p></form>');$('#authSwitch').onclick=()=>accountModal(!register);$('#localAuthForm').onsubmit=async e=>{e.preventDefault();const email=$('#authEmail').value.trim().toLowerCase(),pass=$('#authPassword').value;const b=$('#authSubmit');b.disabled=true;try{let a=S.accounts.find(a=>a.email===email);if(register){if(a)throw new Error('На этом устройстве уже есть аккаунт с таким email');const name=$('#authName').value.trim();if(!name)throw new Error('Укажите имя');const salt=uid(),hash=await digest(pass,salt);a={id:uid(),name,email,handle:'user_'+uid().slice(0,8),salt,hash,bio:'',avatar:null};S.accounts.push(a)}else{if(!a||!a.hash||await digest(pass,a.salt)!==a.hash)throw new Error('Неверный email или пароль локального аккаунта')}S.session=a.id;const ok=await save();applyIdentity();renderFeed();closeModal('workModal');if(ok)toast('Локальный аккаунт открыт')}catch(err){$('#authError').textContent=err.message||'Вход недоступен';b.disabled=false}}}
$('#loginBtn').onclick=()=>accountModal();$('#sideMore').onclick=()=>accountModal();
function applySettings(){document.body.dataset.theme=S.settings.light?'light':'';$('#themeToggle').classList.toggle('on',!S.settings.light);$('#themeToggle').setAttribute('role','switch');$('#themeToggle').setAttribute('aria-label','Тёмная тема');$('#themeToggle').setAttribute('aria-checked',!S.settings.light);$$('[data-setting]').forEach(b=>{const on=!!S.settings[b.dataset.setting];b.classList.toggle('on',on);b.setAttribute('role','switch');b.setAttribute('aria-checked',on);b.setAttribute('aria-label',b.closest('.setting-row').querySelector('h3').textContent)});$$('video').forEach(v=>{if(S.settings.autoplay){v.muted=true;v.autoplay=true}})}
$('#themeBtn').onclick=async()=>{S.settings.light=!S.settings.light;applySettings();await save()};$('#themeToggle').onclick=()=>$('#themeBtn').click();$$('[data-setting]').forEach(b=>b.onclick=async()=>{const key=b.dataset.setting;S.settings[key]=!S.settings[key];applySettings();await save()});
$('#searchInput').oninput=e=>{const q=e.target.value.trim().toLowerCase(),box=$('#searchResults');if(!q){box.classList.remove('open');return}let matches=[];S.posts.filter(p=>p.text.toLowerCase().includes(q)||(p.author||'').toLowerCase().includes(q)).slice(0,6).forEach(p=>matches.push({type:'Публикация',text:p.text,run:()=>{filter='all';renderFeed();go('home');setTimeout(()=>document.querySelector('[data-id="'+p.id+'"]')?.scrollIntoView({behavior:'smooth',block:'center'}),30)}}));S.communities.filter(c=>(c.name+' '+c.description).toLowerCase().includes(q)).forEach(c=>matches.push({type:'Сообщество',text:c.name,run:()=>{go('communities');openCommunity(c.id)}}));S.videos.filter(v=>(v.title+' '+v.description).toLowerCase().includes(q)).forEach(v=>matches.push({type:'Видео',text:v.title,run:()=>{go('videos');playVideo(v.id)}}));S.chats.filter(c=>c.name.toLowerCase().includes(q)).forEach(c=>matches.push({type:'Чат',text:c.name,run:()=>{activeChat=c.id;go('messages')}}));S.accounts.filter(a=>(a.name+' '+a.handle).toLowerCase().includes(q)).forEach(a=>matches.push({type:'Локальный профиль',text:a.name+' @'+a.handle,run:()=>{if(a.id===me().id)go('profile');else work(a.name,profileHTML(a))}}));matches=matches.slice(0,15);box.innerHTML=matches.map((m,i)=>'<button class="search-result" data-match="'+i+'"><b>'+m.type+'</b><small>'+esc(m.text)+'</small></button>').join('')||'<p class="hint" style="padding:10px">Ничего не найдено на этом устройстве</p>';box.classList.add('open');box.querySelectorAll('[data-match]').forEach(b=>b.onclick=()=>{box.classList.remove('open');matches[+b.dataset.match].run()})};
function downloadJSON(){const data={format:'pulse-text-export',version:2,exported:new Date().toISOString(),profiles:S.accounts.map(({hash,salt,avatar,...rest})=>rest),posts:S.posts.map(({file,...rest})=>({...rest,attachment:file?{name:file.name,type:file.type,size:file.size}:null})),communities:S.communities,chats:S.chats,videos:S.videos.map(({file,...rest})=>({...rest,filename:file.name})),settings:S.settings};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='pulse-text-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Экспорт скачан: без файлов и хешей паролей')}
$('#exportData').onclick=downloadJSON;
$('#aboutLocal').onclick=()=>work('PULSE — ваше связанное пространство','<div class="brand-inline large">'+mark+'ULSE</div><p class="hint" style="margin-top:20px">ONE PLATFORM. EVERYTHING CONNECTED.</p><p class="hint">Это автономная одностраничная версия, а не развёрнутая социальная сеть. Работают публикации с файлами, реакции, комментарии, сохранённое, локальные чаты, сообщества с каналами, загрузка и воспроизведение видео, редактирование профиля, поиск, локальные аккаунты и настройки.</p><p class="hint">Данные хранятся в IndexedDB этого браузера. Очистка данных браузера удалит их. Экспорт JSON содержит тексты и метаданные, но не файлы и не пароли; импорт не предусмотрен.</p><p class="hint">Не подключены: серверная БД и API, межпользовательская доставка, WebSocket, звонки, реальные push-уведомления, облачное хранение и транскодирование, модерация и серверная безопасность. Локальные профили не изолированы друг от друга. Статус «только я» — метка, а не контроль доступа.</p>');
document.addEventListener('click',e=>{if(!e.target.closest('.search'))$('#searchResults').classList.remove('open');if(e.target.classList.contains('modal-backdrop')){e.target.querySelectorAll('video').forEach(v=>v.pause());closeModal(e.target.id)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$$('.modal-backdrop.open').forEach(m=>{m.querySelectorAll('video').forEach(v=>v.pause());closeModal(m.id)});$('#searchResults').classList.remove('open');focusBefore?.focus()}if(e.key==='Tab'){const modal=$('.modal-backdrop.open');if(!modal)return;const els=[...modal.querySelectorAll('button,input,textarea,select,a[href],video[controls]')].filter(x=>!x.disabled&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
