function confirmAction(title,description,onConfirm){work(title,'<p class="hint">'+esc(description)+'</p><div class="modal-foot"><button class="ghost" id="cancelAction">Отмена</button><button class="danger-btn" id="confirmAction">Удалить</button></div>');$('#cancelAction').onclick=()=>closeModal('workModal');$('#confirmAction').onclick=async()=>{await onConfirm();closeModal('workModal')}}
const baseRenderProfile=renderProfile;renderProfile=function(){baseRenderProfile();if(me().id==='local'||$('#deleteMyLocalAccount'))return;const b=document.createElement('button');b.id='deleteMyLocalAccount';b.className='danger-btn';b.textContent='Удалить мой аккаунт';b.style.marginTop='18px';b.onclick=()=>confirmAction('Удалить аккаунт?','Будут удалены ваш профиль, публикации, комментарии, видео, чаты и созданные вами сообщества с каналами.',async()=>{const id=me().id;S.posts=S.posts.filter(x=>x.owner!==id);S.videos=S.videos.filter(x=>x.owner!==id);S.chats=S.chats.filter(x=>x.owner!==id);S.communities=S.communities.filter(x=>x.owner!==id);S.accounts=S.accounts.filter(x=>x.id!==id);S.session='local';await save();applyIdentity();renderFeed()});$('#profile .profile-card').append(b)};
const baseRenderFeed=renderFeed;renderFeed=function(){baseRenderFeed();$$('#postList .comment').forEach((node)=>{const p=node.closest('[data-id]'),post=p&&S.posts.find(x=>x.id===p.dataset.id);const commentText=node.querySelector('p');if(!post||!commentText)return;const author=commentText.querySelector('b')?.textContent;if(author!==me().name||node.querySelector('[data-delete-own-comment]'))return;const text=commentText.innerText.replace(author,'').trim();const c=[...post.comments].reverse().find(x=>x.author===author&&x.text===text);if(!c)return;const b=document.createElement('button');b.className='delete-inline';b.textContent='×';b.title='Удалить комментарий';b.dataset.deleteOwnComment=c.id;b.onclick=()=>confirmAction('Удалить комментарий?','Комментарий будет удалён.',async()=>{post.comments=post.comments.filter(x=>x.id!==c.id);await save();renderFeed()});node.append(b)})};
const baseRenderCommunities=renderCommunities;renderCommunities=function(){baseRenderCommunities();$$('#communityGrid .community').forEach((card,i)=>{const c=S.communities[i];if(!c||c.owner!==me().id)return;const b=document.createElement('button');b.className='tool';b.textContent='Удалить';b.onclick=()=>confirmAction('Удалить сообщество?','Сообщество, его каналы и сообщения будут удалены.',async()=>{S.communities=S.communities.filter(x=>x.id!==c.id);await save();renderCommunities();applyIdentity()});card.querySelector('.community-footer')?.append(b)})};
const baseOpenCommunity=openCommunity;openCommunity=function(id,channel='general'){baseOpenCommunity(id,channel);const c=S.communities.find(x=>x.id===id);if(!c||c.owner!==me().id)return;const list=$('#workBody .channel-list');if(list){list.querySelectorAll('[data-channel]').forEach(btn=>{const ch=btn.dataset.channel;if(c.channels.length<2)return;const del=document.createElement('button');del.className='delete-inline';del.textContent='×';del.title='Удалить канал';del.onclick=()=>confirmAction('Удалить канал?','Канал и все его сообщения будут удалены.',async()=>{c.channels=c.channels.filter(x=>x!==ch);delete c.messages[ch];await save();openCommunity(id,c.channels[0]||'general')});btn.after(del)});$('#workBody #channelBody')?.querySelectorAll('.bubble').forEach((bubble,i)=>{const m=(c.messages[channel]||[])[i];if(!m||m.owner!==me().id)return;const del=document.createElement('button');del.className='delete-inline';del.textContent='×';del.title='Удалить сообщение';del.onclick=()=>confirmAction('Удалить сообщение?','Сообщение будет удалено из канала.',async()=>{c.messages[channel]=(c.messages[channel]||[]).filter(x=>x.id!==m.id);await save();openCommunity(id,channel)});bubble.append(del)})}};
const baseRenderChats=renderChats;renderChats=function(){baseRenderChats();$$('.conversation-list [data-room]').forEach(row=>{const c=S.chats.find(x=>x.id===row.dataset.room);if(!c||c.owner!==me().id||row.querySelector('[data-delete-own-chat]'))return;const b=document.createElement('button');b.className='delete-inline';b.textContent='×';b.title='Удалить чат';b.dataset.deleteOwnChat=c.id;b.onclick=e=>{e.stopPropagation();confirmAction('Удалить чат?','Чат и все его сообщения будут удалены.',async()=>{S.chats=S.chats.filter(x=>x.id!==c.id);if(activeChat===c.id)activeChat=null;await save();renderChats()})};row.append(b)});const c=S.chats.find(x=>x.id===activeChat);if(c)$('#chatBody').querySelectorAll('.bubble.me').forEach((bubble,i)=>{const m=c.messages.filter(x=>x.mine)[i];if(!m||bubble.querySelector('[data-delete-own-message]'))return;const b=document.createElement('button');b.className='delete-inline';b.textContent='×';b.title='Удалить сообщение';b.dataset.deleteOwnMessage=m.id;b.onclick=()=>confirmAction('Удалить сообщение?','Сообщение будет удалено из чата.',async()=>{c.messages=c.messages.filter(x=>x.id!==m.id);await save();renderChats()});bubble.append(b)})};
